        // 解除一个后仍 409，只剩未解除的事件
        service.changeStatus("INC-P2", "bob", new StatusRequest(key(), "CONTAINED"));
        assertThatThrownBy(() -> service.completeTask("INC-P1", "T-1", "alice",
