2	
3	/**
4	 * 事件状态机：REPORTED → COMMANDING → CONTAINED → RESOLVED → CLOSED。
5	 * 只允许沿箭头前进一步，不允许跳转或回退；REPORTED → COMMANDING 仅能通过接管完成。
6	 */
7	public enum IncidentStatus {
8	
9	    /** 已上报，尚无指挥人。 */
10	    REPORTED,
11	
12	    /** 已接管，指挥人处置中。 */
13	    COMMANDING,
14	
15	    /** 已控制。 */
16	    CONTAINED,
