package com.example.starter.incident;

/**
 * 处置提案状态机：OPEN → EFFECTIVE 或 OPEN → EXPIRED。
 * OPEN 为投票中；到期前达法定人数生效为 EFFECTIVE；到达到期时刻仍未生效为 EXPIRED。
 * EFFECTIVE 与 EXPIRED 均为终态，不允许再投票、撤回或修订。
 */
public enum DecisionStatus {

    /** 投票中（UTC 时刻位于 [createdAt, expiresAt) 区间）。 */
    OPEN,

    /** 到期前达法定人数，已原子写入任务变更。 */
    EFFECTIVE,

    /** 到达到期时刻仍未达法定人数（含到期时刻当次投票触发的惰性到期）。 */
    EXPIRED;
}

package com.example.starter.incident;

/**
 * 提案投票立场：支持或反对。支持与反对票都必须来自不同的有效角色。
 */
public enum VoteChoice {

    /** 支持。 */
    SUPPORT,

    /** 反对。 */
    OPPOSE;
}

package com.example.starter.incident;

/**
 * 投票记录状态：
 * CAST 为当前版本有效票；任务修订后旧版本票转 STALE，永久保留且不计入新版本；
 * 投票人撤回后转 WITHDRAWN，永久保留、不可恢复，撤回后可在新版本内重新投。
 */
public enum VoteStatus {

    /** 当前版本有效票，计入法定人数。 */
    CAST,

    /** 任务版本变化后失效的旧票，永久保留，不计入新版本。 */
    STALE,

    /** 投票人主动撤回的票，永久保留，不计入法定人数。 */
    WITHDRAWN;
}

package com.example.starter.incident;

/**
 * 提案生效时原子写入的任务变更类型：完成或取消处置任务。
 */
public enum DecisionType {

    /** 生效时将任务 OPEN → DONE（仍须满足全部阻塞事件已解除的门禁）。 */
    TASK_COMPLETE,

    /** 生效时将任务 OPEN → CANCELLED。 */
    TASK_CANCEL;
}

