/**
 * 惰性到期判定：OPEN 提案在当前时刻 ≥ expiresAt（左闭右开）时固化为 EXPIRED。
 * 必须在持有事件行锁与提案行锁时调用，按事务提交顺序与投票/撤回/修订裁决。
 */
private void expireIfDue(DecisionProposal proposal) {
    if (proposal.status() == DecisionStatus.OPEN && !now().isBefore(proposal.expiresAt())) {
        if (decisions.markExpired(proposal.id(), now()) == 0) {
            throw ApiException.conflict("提案已被并发处理: " + proposal.proposalKey());
        }
    }
}

/**
 * 撤回时定位当前版本：提案仍 OPEN 时当前有效版本为任务当前版本；
 * 这里以投票行自身 status=CAST 为准（CAST 票只可能属于最新未失效版本）。
 */
private static int proposalBaseOrCurrentRevision(DecisionProposal proposal) {
    return proposal.baseTaskRevision();
}

