                        .header("X-Actor-Id", "u1")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"commandKey\":\"" + key() + "\"}"))
                .andExpect(status().isGone());
    }

    @Test
    void decisionHttpValidation_422And400() throws Exception {
        commanding("INC-620", "alice");
        task("INC-620", "T-1");
